decorativeCss:
[data-theme="monarch"] body::after{content:"";position:fixed;inset:0;z-index:1;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(130,175,255,.035) 0 1px,transparent 1px 3px)}
[data-theme="monarch"] .pagehead h1{letter-spacing:.06em;text-transform:uppercase;text-shadow:0 0 14px rgba(77,157,255,.35)}
[data-theme="monarch"] .hero .label{letter-spacing:.14em;text-transform:uppercase}
[data-theme="monarch"] .hero .big{text-shadow:0 0 16px rgba(77,157,255,.4)}
[data-theme="monarch"] .card{border-color:color-mix(in srgb,var(--accent) 45%,transparent);background:linear-gradient(160deg,color-mix(in srgb,var(--bg-elev) 94%,var(--accent)),var(--bg-elev));box-shadow:inset 0 0 0 1px rgba(120,190,255,.08),0 0 16px rgba(75,180,255,.07);clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,0 100%)}
[data-theme="monarch"] .screen{animation:monarch-materialize .22s cubic-bezier(.2,.9,.3,1)}
[data-theme="monarch"] .sheet.open{animation:monarch-materialize .2s cubic-bezier(.2,.9,.3,1)}
[data-theme="monarch"] #addBtn{box-shadow:0 0 0 1px rgba(120,190,255,.5),0 0 22px rgba(77,157,255,.55)}
[data-theme="monarch"] nav#tabs{border-top-color:color-mix(in srgb,var(--accent) 40%,transparent);box-shadow:0 -1px 20px rgba(75,180,255,.1)}
[data-theme="monarch"] .chip[aria-pressed="true"],[data-theme="monarch"] .seg button[aria-pressed="true"]{box-shadow:0 0 14px rgba(77,157,255,.45)}
[data-theme="monarch"] .btn.primary{box-shadow:0 0 16px rgba(77,157,255,.4)}
[data-theme="monarch"] .progress > i{box-shadow:0 0 10px color-mix(in srgb,var(--accent) 60%,transparent)}
[data-theme="monarch"] #musicToggle{border:1px solid color-mix(in srgb,var(--accent) 45%,transparent);border-radius:var(--r-sm);color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,transparent)}
[data-theme="monarch"] #musicToggle.playing{box-shadow:0 0 14px rgba(77,157,255,.6);animation:monarch-pulse 1.6s ease-in-out infinite}
[data-theme="monarch"] .game-panel{border-color:color-mix(in srgb,var(--accent) 60%,transparent);box-shadow:inset 0 0 0 1px rgba(120,190,255,.12),0 0 20px rgba(75,180,255,.1)}
[data-theme="monarch"] .game-panel .gp-lv{font-family:var(--font-heading);font-size:20px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--accent);text-shadow:0 0 12px rgba(77,157,255,.4)}
[data-theme="monarch"] .game-panel .gp-streak{font-size:15px;font-weight:700}
[data-theme="monarch"] .game-panel .xpbar{margin-top:10px;height:8px;border-radius:999px;background:var(--bg-elev-2);border:1px solid color-mix(in srgb,var(--accent) 25%,transparent);overflow:hidden}
[data-theme="monarch"] .game-panel .xpbar > i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),#8f6bff);box-shadow:0 0 12px rgba(77,157,255,.6);transition:width .5s var(--spring)}
[data-theme="monarch"] .game-panel .quests{margin-top:12px;display:flex;flex-direction:column;gap:6px}
[data-theme="monarch"] .game-panel .quest{display:flex;align-items:center;gap:8px;font-size:13px;padding:7px 9px;border:1px solid color-mix(in srgb,var(--accent) 22%,transparent);border-radius:var(--r-sm);background:color-mix(in srgb,var(--bg-elev-2) 70%,transparent)}
[data-theme="monarch"] .game-panel .quest .q-box{color:var(--text-faint);font-size:14px}
[data-theme="monarch"] .game-panel .quest .q-label{flex:1}
[data-theme="monarch"] .game-panel .quest .q-xp{color:var(--text-dim);font-variant-numeric:tabular-nums;font-size:12px}
[data-theme="monarch"] .game-panel .quest.done{border-color:color-mix(in srgb,var(--pos) 55%,transparent);box-shadow:0 0 12px color-mix(in srgb,var(--pos) 25%,transparent)}
[data-theme="monarch"] .game-panel .quest.done .q-box{color:var(--pos)}
[data-theme="monarch"] .game-panel .quest.done .q-label{color:var(--text-dim);text-decoration:line-through}
[data-theme="monarch"] #questComplete:not([hidden]){position:fixed;inset:0;z-index:70;display:grid;place-items:center;padding:24px;text-align:center;background:radial-gradient(120% 80% at 50% 40%,color-mix(in srgb,var(--accent) 14%,var(--bg)),var(--bg) 70%)}
[data-theme="monarch"] #questComplete .qc-inner{animation:monarch-questpop .5s cubic-bezier(.2,.9,.3,1)}
[data-theme="monarch"] #questComplete .qc-kicker{font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--accent);margin-bottom:14px}
[data-theme="monarch"] #questComplete .qc-title{font-family:var(--font-heading);font-size:34px;font-weight:800;letter-spacing:.1em;color:var(--text);text-shadow:0 0 24px rgba(77,157,255,.55);border-top:1px solid color-mix(in srgb,var(--accent) 50%,transparent);border-bottom:1px solid color-mix(in srgb,var(--accent) 50%,transparent);padding:14px 8px}
[data-theme="monarch"] #questComplete .qc-sub{margin-top:16px;color:var(--text-dim);font-size:15px}
[data-theme="monarch"] #questComplete .qc-xp{margin-top:10px;font-size:22px;font-weight:800;color:var(--accent);text-shadow:0 0 16px rgba(77,157,255,.5)}
[data-theme="monarch"] #questComplete .qc-hint{margin-top:22px}
@keyframes monarch-materialize{from{opacity:0;transform:scale(.975)}60%{opacity:1}to{opacity:1;transform:none}}
@keyframes monarch-pulse{0%,100%{box-shadow:0 0 10px rgba(77,157,255,.4)}50%{box-shadow:0 0 20px rgba(77,157,255,.75)}}
@keyframes monarch-questpop{0%{opacity:0;transform:scale(.9)}55%{opacity:1}100%{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){[data-theme="monarch"] .screen,[data-theme="monarch"] .sheet.open,[data-theme="monarch"] #questComplete .qc-inner,[data-theme="monarch"] #musicToggle.playing{animation:none}[data-theme="monarch"] .game-panel .xpbar > i{transition:none}}
